begin;
select plan(43);
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
 ('11111111-1111-4111-8111-111111111111','authenticated','authenticated','claim-a@example.test','x',now(),'{}','{}',now(),now()),
 ('33333333-3333-4333-8333-333333333333','authenticated','authenticated','claim-b@example.test','x',now(),'{}','{}',now(),now());
insert into public.outfits(id,user_id,look_name,ai_reasoning,occasion)
select ('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'11111111-1111-4111-8111-111111111111','Quiet Morning',null,'everyday' from generate_series(1,8) n;
insert into public.outfits(id,user_id,look_name,occasion) values ('44444444-4444-4444-8444-444444444444','33333333-3333-4333-8333-333333333333','Foreign','work');
create temporary table responses(label text primary key, payload jsonb);
grant all on responses to authenticated;
select ok(not has_function_privilege('anon','public.claim_outfit_text_translations(uuid[],text)','execute'),'anon cannot claim');
select ok(not has_function_privilege('anon','public.finish_outfit_text_translations(text,jsonb)','execute'),'anon cannot finish');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select throws_ok($$select public.claim_outfit_text_translations('{}','uk')$$,'22023',null,'empty batch refused');
select throws_ok($$select public.claim_outfit_text_translations(array[null::uuid],'uk')$$,'22023',null,'null id refused');
select throws_ok($$select public.claim_outfit_text_translations(array(select ('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,7) n),'uk')$$,'22023',null,'seventh raw id refused');
select throws_ok($$select public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'ru')$$,'22023',null,'unshipped target refused');
select is(public.claim_outfit_text_translations(array['44444444-4444-4444-8444-444444444444'::uuid],'uk'),'[]'::jsonb,'foreign outfit cannot be claimed');
insert into responses values('source',public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'en-US'));
select is((select payload->0->>'status' from responses where label='source'),'source','original language needs no translation');
insert into responses values('first',public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid],'uk'));
select is((select jsonb_array_length(payload) from responses where label='first'),1,'duplicate ids reserve once');
select is((select payload->0->>'status' from responses where label='first'),'claimed','first claim obtains a lease');
select is((select payload->0->'source'->'why' from responses where label='first'),'null'::jsonb,'nullable original why preserved');
select is(public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'uk')->0->>'status','busy','live lease cannot be claimed twice');
select throws_ok($$select public.finish_outfit_text_translations('uk','[{"outfitId":"bad","leaseToken":"bad","status":"ready","name":"x","why":null}]')$$,'22023',null,'invalid completion uuid rejected');
select throws_ok($$select public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='first'),'status','ready','name',repeat('x',41),'why',null)))$$,'22023',null,'oversized output rejected');
select throws_ok($$select public.finish_outfit_text_translations('uk','{}')$$,'22023',null,'object completion is not an array');
select throws_ok($$select public.finish_outfit_text_translations('ru','[]')$$,'22023',null,'unshipped completion target refused');
select throws_ok($$select public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='first'),'status','ready','name','x','why','Invented reasoning')))$$,'22023',null,'null source reasoning cannot become invented prose');
select throws_ok($$select public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='first'),'status','failed'),jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='first'),'status','failed')))$$,'22023',null,'duplicate completion IDs rejected before writes');
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='first'),'status','ready','name','Тихий ранок','why',null)))),1,'owned completion accepted');
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='first'),'status','ready','name','Again','why',null)))),0,'duplicate completion ignored');
reset role;
select is((select reserved from public.outfit_translation_days where user_id='11111111-1111-4111-8111-111111111111'),1,'only one reservation spent');
select is((select completed from public.outfit_translation_days where user_id='11111111-1111-4111-8111-111111111111'),1,'completion counted once');
update public.outfit_translation_days set reserved=60 where user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select is(public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'uk')->0->>'status','ready','ready hit works at exhausted budget');
select is(public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000002'::uuid],'uk')->0->>'status','limited','new claim cannot exceed 60');
reset role;
update public.outfit_translation_days set reserved=1 where user_id='11111111-1111-4111-8111-111111111111';
update public.outfits set look_name='Changed' where id='20000000-0000-4000-8000-000000000001';
set local role authenticated;
insert into responses values('changed',public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'uk'));
select is((select payload->0->>'status' from responses where label='changed'),'claimed','new source requires new translation');
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='first'),'status','ready','name','Stale','why',null)))),0,'old token cannot replace new source');
reset role;
update public.outfit_text_translations set leased_until=now()-interval '1 second' where outfit_id='20000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='changed'),'status','ready','name','Expired','why',null)))),0,'expired lease cannot complete');
insert into responses values('expired',public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'uk'));
select isnt((select payload->0->>'leaseToken' from responses where label='expired'),(select payload->0->>'leaseToken' from responses where label='changed'),'expired lease gets a new token');
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='expired'),'status','failed')))),0,'failed provider installs no text');
select is(public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'uk')->0->>'status','cooldown','failure waits before new paid work');
reset role;
select is((select reserved from public.outfit_translation_days where user_id='11111111-1111-4111-8111-111111111111' and day=(now() at time zone 'UTC')::date),3,'failure retains reservations and cooldown is free');
update public.outfits set ai_reasoning='Why' where id='20000000-0000-4000-8000-000000000001';
set local role authenticated;
insert into responses values('why-change',public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000001'::uuid],'uk'));
select is((select payload->0->>'status' from responses where label='why-change'),'claimed','new reasoning bypasses old cooldown');
reset role;
update public.outfits set text_locale='en-GB' where id='20000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000001','leaseToken',(select payload->0->>'leaseToken' from responses where label='why-change'),'status','ready','name','Wrong language','why','Description')))),0,'changed source locale rejects completion');
select is((select count(*)::int from public.outfit_text_translations where outfit_id='20000000-0000-4000-8000-000000000001'),0,'owned stale snapshot removed');
insert into responses values('delete',public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000002'::uuid],'uk'));
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000002','leaseToken',(select payload->0->>'leaseToken' from responses where label='delete'),'status','ready','name','Foreign completion','why',null)))),0,'foreign owner cannot finish even with the token');
select is(public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000002'::uuid],'uk'),'[]'::jsonb,'reverse owner isolation');
reset role;
delete from public.outfits where id='20000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000002','leaseToken',(select payload->0->>'leaseToken' from responses where label='delete'),'status','ready','name','Deleted','why',null)))),0,'deleted look cannot install text');
reset role;
update public.outfits set look_name=repeat('x',121) where id='20000000-0000-4000-8000-000000000003';
set local role authenticated;
select is(public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000003'::uuid],'uk'),'[]'::jsonb,'oversized source skipped without provider');
insert into responses values('midnight',public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000004'::uuid],'uk'));
reset role;
insert into public.outfit_translation_days(user_id,day,reserved) values('11111111-1111-4111-8111-111111111111',(now() at time zone 'UTC')::date-1,1);
update public.outfit_text_translations set claim_day=(now() at time zone 'UTC')::date-1 where outfit_id='20000000-0000-4000-8000-000000000004';
set local role authenticated;
select is(cardinality(public.finish_outfit_text_translations('uk',jsonb_build_array(jsonb_build_object('outfitId','20000000-0000-4000-8000-000000000004','leaseToken',(select payload->0->>'leaseToken' from responses where label='midnight'),'status','ready','name','After midnight','why',null)))),1,'completion across UTC midnight accepted');
reset role;
select is((select completed from public.outfit_translation_days where user_id='11111111-1111-4111-8111-111111111111' and day=(now() at time zone 'UTC')::date-1),1,'completion charged to original claim day');
select is((select look_name from public.outfits where id='20000000-0000-4000-8000-000000000004'),'Quiet Morning','original name unchanged');
select is((select count(*)::int from public.generation_events where user_id='11111111-1111-4111-8111-111111111111'),0,'translations never spend outfit rerolls');
delete from public.profiles where id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select throws_ok($$select public.claim_outfit_text_translations(array['20000000-0000-4000-8000-000000000004'::uuid],'uk')$$,'42501',null,'stale JWT without live profile refused');
select * from finish();
rollback;
